
import Group from 'vux/src/components/group/index.vue'
import XTable from 'vux/src/components/x-table/index.vue'
import XButton from 'vux/src/components/x-button/index.vue'

import { mapState, mapActions } from 'vuex'
import { loadRenjunetDB, queryRenjunetPosition, formatRenjuRule } from '@/ai/renjunet'

export default {
name: 'book-games',
components: {
Group,
XTable,
XButton,
},
data() {
return {
limit: 200,
cellTooltip: null,
stats: {
total: 0,
games: [],
},
}
},
computed: {
...mapState('position', ['position', 'size', 'blocked']),
...mapState('settings', ['bookNormalizeOrder']),
visibleGames() {
return this.stats.games.slice(0, this.limit)
},
},
mounted() {
this.refresh()
},
activated() {
this.refresh()
},
methods: {
...mapActions('book', ['loadGame']),
async refresh() {
this.limit = 200
await loadRenjunetDB()
if (this.size === 15 && this.blocked.length === 0) {
const res = queryRenjunetPosition(this.position, {
normalizeOrder: this.bookNormalizeOrder,
maxGames: 5000,
})
if (res) this.stats = res
} else {
this.stats = { total: 0, games: [] }
}
},
formatBookRule(rule) {
return formatRenjuRule(rule)
},
formatBookResult(res) {
if (res === 2) return this.$t('game.book.blackWin')
if (res === 1) return this.$t('game.book.draw')
if (res === 0) return this.$t('game.book.whiteWin')
return '-'
},
onBookCellClick(event, text) {
const el = event.currentTarget
if (el && el.scrollWidth > el.clientWidth) {
if (this.cellTooltip && this.cellTooltip.text === text) {
this.cellTooltip = null
return
}
event.stopPropagation()
const rect = el.getBoundingClientRect()
this.cellTooltip = {
text,
x: Math.min(Math.max(8, rect.left), window.innerWidth - 280),
y: Math.max(8, rect.top - 36),
}
} else {
this.cellTooltip = null
}
},
onSelectGame(g) {
this.loadGame({ gameIdx: g.gameIdx, transform: g.transform })
this.$router.back()
},
},
}
