const BOARD_SIZE = 15
const CELL_COUNT = BOARD_SIZE * BOARD_SIZE

// Precompute 8 D4 symmetry maps and their inverses on 15x15 (idx = y * 15 + x)
const D4_FWD = []
const D4_INV = []

function transformXY(x, y, t) {
  const n = BOARD_SIZE - 1
  switch (t) {
    case 0:
      return [x, y]
    case 1:
      return [n - y, x]
    case 2:
      return [n - x, n - y]
    case 3:
      return [y, n - x]
    case 4:
      return [n - x, y]
    case 5:
      return [n - y, n - x]
    case 6:
      return [x, n - y]
    case 7:
      return [y, x]
  }
}

for (let t = 0; t < 8; t++) {
  const fwd = new Uint8Array(CELL_COUNT)
  const inv = new Uint8Array(CELL_COUNT)
  for (let y = 0; y < BOARD_SIZE; y++) {
    for (let x = 0; x < BOARD_SIZE; x++) {
      const src = y * BOARD_SIZE + x
      const [tx, ty] = transformXY(x, y, t)
      const dst = ty * BOARD_SIZE + tx
      fwd[src] = dst
      inv[dst] = src
    }
  }
  D4_FWD.push(fwd)
  D4_INV.push(inv)
}

let db = null
let loadPromise = null

export async function loadRenjunetDB() {
  if (db) return db
  if (loadPromise) return loadPromise

  loadPromise = (async () => {
    const base = `${process.env.BASE_URL}renjunet/`
    const [metaRes, binRes] = await Promise.all([
      fetch(`${base}renjunet_meta.json`),
      fetch(`${base}renjunet_games.bin`),
    ])
    if (!metaRes.ok || !binRes.ok) {
      throw new Error(`Failed to load RenjuNet book (${metaRes.status}/${binRes.status})`)
    }
    const [meta, buf] = await Promise.all([metaRes.json(), binRes.arrayBuffer()])
    const view = new DataView(buf)
    const magic = view.getUint32(0, true)
    if (magic !== 0x524e4a31) {
      throw new Error('Invalid RenjuNet binary header')
    }
    const gameCount = view.getUint32(4, true)
    const bytes = new Uint8Array(buf)

    const blackIdx = new Uint16Array(gameCount)
    const whiteIdx = new Uint16Array(gameCount)
    const tourIdx = new Uint16Array(gameCount)
    const ruleId = new Uint8Array(gameCount)
    const result = new Uint8Array(gameCount)
    const moveCount = new Uint8Array(gameCount)
    const moveOffset = new Uint32Array(gameCount)

    let pos = 8
    for (let g = 0; g < gameCount; g++) {
      blackIdx[g] = view.getUint16(pos, true)
      whiteIdx[g] = view.getUint16(pos + 2, true)
      tourIdx[g] = view.getUint16(pos + 4, true)
      ruleId[g] = bytes[pos + 6]
      result[g] = bytes[pos + 7]
      const mc = bytes[pos + 8]
      moveCount[g] = mc
      moveOffset[g] = pos + 9
      pos += 9 + mc
    }

    db = {
      meta,
      gameCount,
      bytes,
      blackIdx,
      whiteIdx,
      tourIdx,
      ruleId,
      result,
      moveCount,
      moveOffset,
    }
    return db
  })().catch((err) => {
    loadPromise = null
    throw err
  })

  return loadPromise
}

export function queryRenjunetPosition(position, { normalizeOrder = true, maxGames = 100 } = {}) {
  if (!db) return null

  const k = position.length
  const sideToMove = k % 2 === 0 ? 1 : 2 // 1 = BLACK, 2 = WHITE
  const { gameCount, bytes, blackIdx, whiteIdx, tourIdx, ruleId, result, moveCount, moveOffset, meta } = db

  const boards = []
  const seqs = []
  for (let t = 0; t < 8; t++) {
    const fwd = D4_FWD[t]
    if (normalizeOrder) {
      const b = new Uint8Array(CELL_COUNT)
      for (let i = 0; i < k; i++) {
        const idx = position[i][1] * BOARD_SIZE + position[i][0]
        b[fwd[idx]] = (i & 1) + 1
      }
      boards.push(b)
    } else {
      const s = new Uint8Array(k)
      for (let i = 0; i < k; i++) {
        const idx = position[i][1] * BOARD_SIZE + position[i][0]
        s[i] = fwd[idx]
      }
      seqs.push(s)
    }
  }

  // Precompute canonical next-move map under the stabilizer subgroup Stab(s) of D4
  // so that D4-equivalent candidate moves (s, m) are merged together.
  const stabTransforms = [0]
  for (let t = 1; t < 8; t++) {
    let same = true
    if (normalizeOrder) {
      const b0 = boards[0]
      const bt = boards[t]
      for (let idx = 0; idx < CELL_COUNT; idx++) {
        if (b0[idx] !== bt[idx]) {
          same = false
          break
        }
      }
    } else {
      const s0 = seqs[0]
      const st = seqs[t]
      for (let i = 0; i < k; i++) {
        if (s0[i] !== st[i]) {
          same = false
          break
        }
      }
    }
    if (same) stabTransforms.push(t)
  }

  const isBetterUpperRight = (a, b) => {
    const ax = a % BOARD_SIZE
    const ay = Math.floor(a / BOARD_SIZE)
    const bx = b % BOARD_SIZE
    const by = Math.floor(b / BOARD_SIZE)
    const aUR = ax >= 7 && ay <= 7 ? 1 : 0
    const bUR = bx >= 7 && by <= 7 ? 1 : 0
    if (aUR !== bUR) return aUR > bUR
    const aU = ay <= 7 ? 1 : 0
    const bU = by <= 7 ? 1 : 0
    if (aU !== bU) return aU > bU
    const aR = ax >= 7 ? 1 : 0
    const bR = bx >= 7 ? 1 : 0
    if (aR !== bR) return aR > bR
    if (ay !== by) return ay < by
    return ax < bx
  }

  const canonNextIdx = new Uint8Array(CELL_COUNT)
  for (let idx = 0; idx < CELL_COUNT; idx++) {
    let best = idx
    for (let j = 0; j < stabTransforms.length; j++) {
      const mapped = D4_FWD[stabTransforms[j]][idx]
      if (isBetterUpperRight(mapped, best)) best = mapped
    }
    canonNextIdx[idx] = best
  }

  let total = 0
  let blackWins = 0
  let draws = 0
  let whiteWins = 0
  let unknown = 0

  const nextMap = new Map()
  const matchedGames = []

  for (let g = gameCount - 1; g >= 0; g--) {
    const mc = moveCount[g]
    if (mc < k) continue

    const off = moveOffset[g]
    let matchedT = -1

    if (k === 0) {
      matchedT = 0
    } else if (normalizeOrder) {
      for (let t = 0; t < 8; t++) {
        const b = boards[t]
        let ok = true
        for (let i = 0; i < k; i++) {
          if (b[bytes[off + i]] !== (i & 1) + 1) {
            ok = false
            break
          }
        }
        if (ok) {
          matchedT = t
          break
        }
      }
    } else {
      for (let t = 0; t < 8; t++) {
        const s = seqs[t]
        let ok = true
        for (let i = 0; i < k; i++) {
          if (bytes[off + i] !== s[i]) {
            ok = false
            break
          }
        }
        if (ok) {
          matchedT = t
          break
        }
      }
    }

    if (matchedT === -1) continue

    total++
    const res = result[g]
    if (res === 2) blackWins++
    else if (res === 1) draws++
    else if (res === 0) whiteWins++
    else unknown++

    if (mc > k) {
      const nextIdx = canonNextIdx[D4_INV[matchedT][bytes[off + k]]]
      let entry = nextMap.get(nextIdx)
      if (!entry) {
        entry = {
          idx: nextIdx,
          pos: [nextIdx % BOARD_SIZE, Math.floor(nextIdx / BOARD_SIZE)],
          count: 0,
          blackWins: 0,
          draws: 0,
          whiteWins: 0,
          scoredCount: 0,
          moverScoreSum: 0,
        }
        nextMap.set(nextIdx, entry)
      }
      entry.count++
      if (res === 2) {
        entry.blackWins++
        entry.scoredCount++
        entry.moverScoreSum += sideToMove === 1 ? 1 : 0
      } else if (res === 1) {
        entry.draws++
        entry.scoredCount++
        entry.moverScoreSum += 0.5
      } else if (res === 0) {
        entry.whiteWins++
        entry.scoredCount++
        entry.moverScoreSum += sideToMove === 2 ? 1 : 0
      }
    }

    if (matchedGames.length < maxGames) {
      const tInfo = meta.tournaments[tourIdx[g]] || ['', '']
      matchedGames.push({
        gameIdx: g,
        transform: matchedT,
        black: meta.players[blackIdx[g]] || '?',
        white: meta.players[whiteIdx[g]] || '?',
        tournament: tInfo[0] || '',
        year: tInfo[1] || '',
        rule: meta.rules[String(ruleId[g])] || String(ruleId[g]),
        result: res,
        moveCount: mc,
        nextPos:
          mc > k
            ? [
                D4_INV[matchedT][bytes[off + k]] % BOARD_SIZE,
                Math.floor(D4_INV[matchedT][bytes[off + k]] / BOARD_SIZE),
              ]
            : null,
      })
    }
  }

  const nextMoves = Array.from(nextMap.values())
    .map((e) => ({
      ...e,
      scoreRate: e.scoredCount > 0 ? e.moverScoreSum / e.scoredCount : null,
    }))
    .sort((a, b) => b.count - a.count)

  const scoredTotal = blackWins + draws + whiteWins
  const totalScoreSum =
    sideToMove === 1 ? blackWins + 0.5 * draws : whiteWins + 0.5 * draws

  return {
    sideToMove,
    total,
    blackWins,
    draws,
    whiteWins,
    unknown,
    scoreRate: scoredTotal > 0 ? totalScoreSum / scoredTotal : null,
    nextMoves,
    games: matchedGames,
  }
}

export const RENJU_RULE_ZH = {
  Classic: '五手两打',
  Taraguchi: '塔拉山口',
  Sakata: '坂田',
  Tarannikov: '塔拉尼科夫',
  Yamaguchi: '山口',
  Jonsson: '琼森',
  Rejection: '拒绝',
  Experimental: '实验',
  Soosyrv: '索索夫',
  LianHuan: '连换',
  'Soosyrv-10': '索索夫-10',
  'LianHuan-5': '连换-5',
  'Taraguchi-7': '塔拉山口-7',
  'Super Sakata': '超级坂田',
  'Soosyrv-5': '索索夫-5',
  'Yamasyrv-5': '山索-5',
  'Soosyrv-7': '索索夫-7',
  'Yamasyrv-7': '山索-7',
  'Yamasyrv-8': '山索-8',
  'Soosyrv-8 (with indulgence)': '索索夫-8(宽容)',
  'Soosyrv-8': '索索夫-8',
  'Taraguchi-10': '塔拉山口-10',
  'Swap-5 free': '五手自由交换',
  'Super Taraguchi-10': '超级塔拉山口-10',
}

export function formatRenjuRule(rule) {
  if (!rule) return '-'
  return RENJU_RULE_ZH[rule] || rule
}

export function getRenjunetGameMoves(gameIdx, transform = 0) {
  if (!db || gameIdx < 0 || gameIdx >= db.gameCount) return []
  const off = db.moveOffset[gameIdx]
  const mc = db.moveCount[gameIdx]
  const inv = D4_INV[transform] || D4_INV[0]
  const moves = []
  for (let i = 0; i < mc; i++) {
    const idx = inv[db.bytes[off + i]]
    moves.push([idx % BOARD_SIZE, Math.floor(idx / BOARD_SIZE)])
  }
  return moves
}
